{"code":"import json, numpy as np, pandas as pd
with open("evaluations.json") as f:
    data = json.load(f)
df = pd.DataFrame([
    {**{x["ingredient"]: x["fraction"] for x in d["recipe"]}, "y": d["target_dissimilarity"], "iter": d["iteration"]}
    for d in data
]).fillna(0)
print(df[["iter", "y", "textured vegetable protein", "pea protein", "coconut oil", "sunflower oil", "potato starch", "flavours"]])
"}
